mapper.select:
SELECT id,paper_no,fixed_paper_id,fixed_paper_code,fixed_paper_version,status,started_at,due_at,submitted_at,objective_score,
       translation_self_score,writing_self_score,self_score_total
FROM exam_paper WHERE user_id=#{userId}
ORDER BY started_at DESC,id DESC LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE exam_answer SET answer_content=#{answer.answerContent},answer_version=#{answer.answerVersion},
       saved_at=#{answer.savedAt},updated_at=#{answer.savedAt}
WHERE paper_id=#{answer.paperId} AND paper_item_id=#{answer.paperItemId} AND answer_version=#{expectedVersion}

UPDATE exam_paper SET status=#{status},submitted_at=#{submittedAt},objective_score=#{objectiveScore},
       version=version+1,updated_at=#{updatedAt}
WHERE id=#{id} AND user_id=#{userId} AND status='IN_PROGRESS' AND version=#{version}

UPDATE exam_paper SET translation_self_score=#{translationSelfScore},writing_self_score=#{writingSelfScore},
       self_score_total=#{selfScoreTotal},version=version+1,updated_at=#{updatedAt}
WHERE id=#{id} AND user_id=#{userId} AND status IN ('SUBMITTED','AUTO_SUBMITTED') AND version=#{version}
